arguments.new_string:
        return ret


class Auto(object):
    """The ``Auto`` specifier type enables automatic type-based handling
    of data during glom operations.

    When used, ``Auto`` instructs glom to automatically determine the
    appropriate operation based on the target's type. For example, when
    applied to a dict, it will perform item access; when applied to a
    list, it will iterate over items.

    This is useful for creating generic specifications that work across
    different data types without explicit type checking.

    >>> from glom import glom, Auto
    >>> # Auto can be used to create flexible specs
    >>> spec = Auto()
    """
    def __repr__(self):
        return 'Auto()'

    def glomit(self, target, scope):
        return target


class Fill(object):
    """The ``Fill`` specifier type fills in missing values or applies
    default transformations to data.

    Fill can be used to ensure that certain keys or attributes exist
    in the target data, filling them with defaults if they're missing.

    Args:
       spec: A spec to apply to the target (defaults to T)
       default: A value to use when the spec returns None or raises
       **kwargs: Additional keyword arguments passed through

    >>> from glom import glom, Fill, T
    >>> target = {'a': 1}
    >>> glom(target, Fill('b', default=0))
    {'a': 1, 'b': 0}
    """
    def __init__(self, spec=T, default=None, **kwargs):
        self.spec = spec
        self.default = default
        self.kwargs = kwargs

    def __repr__(self):
        cn = self.__class__.__name__
        if self.default is not None:
            return '%s(%r, default=%r)' % (cn, self.spec, self.default)
        return '%s(%r)' % (cn, self.spec)

    def glomit(self, target, scope):
        try:
            result = scope[glom](target, self.spec, scope)
            if result is None and self.default is not None:
                return self.default
            return result
        except Exception:
            if self.default is not None:
                return self.default
            raise


class Iter(object):
    """The ``Iter`` specifier type iterates over the target data.

    When applied to an iterable target, ``Iter`` will iterate over all
    items. When combined with other specifiers, it allows for mapping
    operations over collections.

    Args:
       subspec: An optional sub-spec to apply to each item during iteration

    >>> from glom import glom, Iter, T
    >>> target = [1, 2, 3]
    >>> glom(target, Iter(T * 2))
    [2, 4, 6]
    """
    def __init__(self, subspec=T):
        self.subspec = subspec

    def __repr__(self):
        cn = self.__class__.__name__
        return '%s(%r)' % (cn, self.subspec)

    def glomit(self, target, scope):
        iterate = scope[TargetRegistry].get_handler('iterate', target, path=scope[Path])
        iterator = iterate(target)
        return [scope[glom](item, self.subspec, scope) for item in iterator]


class Let(object):
    """The ``Let`` specifier type binds variables within a spec context.

    Let allows you to define intermediate variables that can be used
    by subsequent specs in the same specification. This is similar to
    let bindings in functional programming languages.

    Args:
       name: The name of the variable to bind
       value: The spec or value to assign to the variable
       body: The spec that uses the bound variable

    >>> from glom import glom, Let, T
    >>> target = {'a': 5, 'b': 3}
    >>> glom(target, Let('sum', ('a', 'b'), lambda s: s['a'] + s['b']))
    8
    """
    def __init__(self, name, value, body):
        self.name = name
        self.value = value
        self.body = body

    def __repr__(self):
        cn = self.__class__.__name__
        return '%s(%r, %r, %r)' % (cn, self.name, self.value, self.body)

    def glomit(self, target, scope):
        # Evaluate the value spec
        val = scope[glom](target, self.value, scope)
        # Create a new scope with the bound variable
        new_scope = dict(scope)
        new_scope[self.name] = val
        # Evaluate the body in the new scope
        return scope[glom](target, self.body, new_scope)


class ROOT(object):
    """The ``ROOT`` specifier represents the root/target of the glom operation.

    Unlike ``T``, which represents the current target at any level of
    nesting, ``ROOT`` always refers to the original input data that was
    passed to glom. This is useful when you need to access the original
    data while processing nested structures.

    >>> from glom import glom, ROOT, T
    >>> target = {'a': {'b': 1}}
    >>> # Access the root even when deeply nested
    >>> glom(target, (T['a'], ROOT))
    ({'b': 1}, {'a': {'b': 1}})
    """
    def __repr__(self):
        return 'ROOT'

    def glomit(self, target, scope):
        # Return the original root target
        # In glom's architecture, we need to get this from scope
        return scope.get('_root', target)


class Invoke(object):
    """The ``Invoke`` specifier type invokes/calls a function with the target.

    Similar to ``Call``, but provides a more explicit interface for
    invoking functions. Invoke can take positional arguments and
    keyword arguments, and supports both direct callables and
    attribute/method lookups.

    Args:
       func: A callable to invoke, or a spec/T expression that evaluates to one
       args: Optional positional arguments (can be specs)
       kwargs: Optional keyword arguments (can be specs)

    >>> from glom import glom, Invoke, T
    >>> target = [1, 2, 3]
    >>> glom(target, Invoke(sum))
    6
    """
    def __init__(self, func, args=None, kwargs=None):
        if args is None:
            args = ()
        if kwargs is None:
            kwargs = {}
        self.func = func
        self.args = args
        self.kwargs = kwargs

    def __repr__(self):
        cn = self.__class__.__name__
        if self.args or self.kwargs:
            return 'Invoke(%r, args=%r, kwargs=%r)' % (self.func, self.args, self.kwargs)
        return 'Invoke(%r)' % self.func

    def glomit(self, target, scope):
        def _eval(t):
            if type(t) in (Spec, TType, ROOT):
                return scope[glom](target, t, scope)
            return t

        func = _eval(self.func)
        args = [_eval(a) for a in self.args] if self.args else []
        kwargs = {k: _eval(v) for k, v in self.kwargs.items()} if self.kwargs else {}

        return func(*args, **kwargs)


